-- Check: sample records per register (10 each).
SELECT l.register_key, count(r.id) AS records
FROM public.local_registers l
LEFT JOIN public.local_register_records r ON r.register_id = l.id AND r.is_deleted = FALSE
WHERE l.id IN ('00000000-0000-4000-9003-000000000020'::uuid, '00000000-0000-4000-9003-000000000021'::uuid, '00000000-0000-4000-9003-000000000022'::uuid, '00000000-0000-4000-9003-000000000023'::uuid, '00000000-0000-4000-9003-000000000024'::uuid, '00000000-0000-4000-9003-000000000025'::uuid, '00000000-0000-4000-9003-000000000026'::uuid)
GROUP BY l.register_key ORDER BY l.register_key;
